      final ex = AdoToolExecutor(f.client);
      await expectLater(
          ex.execute('ado_attach_file',
              {'id': 4, 'name': 'r', 'filePath': '/no/such'}),
          throwsA(isA<FileSystemException>()));
      expect(f.adapter.calls, isEmpty);
      await expectLater(
          ex.execute(
              'ado_attach_file', {'id': 4, 'name': 'r', 'filePath': file.path}),
          throwsStateError);
