    table.forEach((input, ref) {
      test('$input -> $ref', () {
        expect(
            wire(call(
                'ado_update_field', {'id': 3, 'field': input, 'value': 'v'})),
            patched('3', _setOp(ref, 'v')));
      });
    });
  });
}

void _priorityTests() {
  group('ado_set_priority', () {
    test('names and numbers map to a numeric patch value', () {
      const cases = {
        '1': 1,
        ' Blocker ': 1,
        'HIGH': 2,
        'major': 2,
        'Medium': 3,
        'normal': 3,
        'trivial': 4,
        'lowest': 4,
