  Future<Map<String, dynamic>> updateWorkItem(
    int id,
    Map<String, dynamic> fields,
  ) async {
    final body = await _http.patchPatch(
      'wit/workitems/$id',
      body: jsonEncode([
        for (final entry in fields.entries)
          {'op': 'add', 'path': '/fields/${entry.key}', 'value': entry.value},
      ]),
    );

