/// Wire shape of a PATCH echo: method, path, content type and patch ops.
Map<String, Object?> wire(Map<String, dynamic> echo) => {
      'method': echo['method'],
      'path': echo['path'],
      'type': echo['headers']['Content-Type'],
      'patch': patchOf(echo),
