)
public String setPriority(
        @MCPParam(name = "id", description = "The work item ID", required = true, aliases = {"key"})
        String workItemId,
        @MCPParam(name = "priority", description = "Priority number 1-4 or a priority name", required = true, example = "High")
        String priority
