      _handlers = {
    'ado_test': (_) => _client.testConnection(),
    'ado_get_work_item': (a) => _client.getWorkItem(_id(a)),
    ..._ticketOpHandlers(_client.workItemOps),
    'ado_update_work_item': (a) => _client.updateWorkItem(
          _id(a),
